'use strict';




let checkNames=[],checkCatalog=[],sourcesDirty=false;
async function loadCheckCatalog(){
 const data=await api('checks');checkCatalog=data.checks;checkNames=checkCatalog.map(row=>row.name);
 $('ruleSettings').replaceChildren();
 for(const row of checkCatalog){
  const label=node('label'),caption=node('span',row.title[lang]||row.title.en||row.name);caption.dataset.checkLabel=row.name;
  const select=node('select');select.name='check_'+row.name;
  for(const mode of row.locked?['required']:['required','auto','off','conditional']){const option=node('option',t(mode));option.value=mode;option.dataset.t=mode;select.append(option);}
  select.value=row.mode;select.disabled=row.locked;
  label.append(caption,select,node('small',row.description));$('ruleSettings').append(label);
 }
}
let currentView='review',settingsSnapshot=null,dirty=false,queuePage=0,reportsPage=0,lastQueueSignature='',connectionBusy=false;
function showView(view,load=true){currentView=view;document.querySelectorAll('[data-panel]').forEach(e=>e.hidden=e.dataset.panel!==view);document.querySelectorAll('[data-view]').forEach(e=>{e.classList.toggle('active',e.dataset.view===view);e.setAttribute('aria-current',e.dataset.view===view?'page':'false')});$('welcome').hidden=view!=='review'||Boolean(selected);if(view==='settings')$('setup').open=true;if(view==='history'&&load)safe(historyLoad);if(view==='monitor')safe(queueLoad);}
document.querySelectorAll('[data-view]').forEach(e=>e.onclick=()=>showView(e.dataset.view));
$('startDemo').onclick=()=>{$('sourceFilter').value='demo';showView('review');if(state?.messages.length)select(state.messages.find(m=>m.source==='demo'));};
$('connectAI').onclick=()=>showView('settings');
$('startFile').onclick=()=>$('file').click();
function configureMailbox(){showView('settings');$('mailSettings').open=true;$('settings').elements.imap_host.focus();}
$('startMailbox').onclick=configureMailbox;$('editMailbox').onclick=configureMailbox;
$('sourceFilter').onchange=renderMessages;
renderMessages=function(){if(!state)return;const box=$('messages');box.replaceChildren();const messages=state.messages.filter(m=>$('sourceFilter').value==='demo'?m.source==='demo':m.source!=='demo');$('count').textContent=messages.length;for(const m of messages){const b=node('button',undefined,'message'+(selected===m.id?' active':''));b.append(node('span',m.source==='demo'?t('samples'):m.source.toUpperCase(),'badge'),node('strong',m.subject||t('messageRef')+' '+m.id.slice(0,12)),node('small',m.sender));b.onclick=()=>{if(!running)select(m)};box.append(b);}if(!messages.length)box.append(node('p',t('noOwnMessages'),'muted'));};
function updateOAuthFields(){fieldVisible('imap_password',$('settings').elements.imap_auth.value==='password');$('oauthHelp').hidden=$('settings').elements.imap_auth.value!=='oauth2';}
$('settings').elements.imap_auth.onchange=updateOAuthFields;
function connectionData(){const f=$('settings').elements,p=f.provider.value;return {provider:p,model:f.model.value.trim(),base_url:['local','compatible'].includes(p)?f.base_url.value.trim():'',api_key:f.api_key.value.trim(),allow_external:p==='local'?false:f.allow_external.checked};}
function collectSettings(){const data={};for(const el of $('settings').elements){if(el.name&&!el.disabled&&!el.name.startsWith('check_'))data[el.name]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):['enabled_skills','plugins'].includes(el.name)?el.value.split(',').map(x=>x.trim()).filter(Boolean):el.value.trim();}data.check_modes={};for(const n of checkNames)data.check_modes[n]=$('settings').elements.namedItem('check_'+n).value;return {...data,...connectionData()};}
function markDirty(){dirty=true;$('draftState').textContent=t('unsaved');$('connectionResult').textContent='';}
$('settings').addEventListener('input',markDirty);$('settings').addEventListener('change',markDirty);
function syncConnectionHints(){const d=connectionData();$('localPresetLabel').hidden=d.provider!=='local';const endpoint=d.base_url||'http://127.0.0.1:1234/v1';$('localPreset').value=['http://127.0.0.1:1234/v1','http://127.0.0.1:11434/v1'].includes(endpoint)?endpoint:'custom';$('keyState').hidden=d.provider==='local';const same=settingsSnapshot&&d.provider===settingsSnapshot.provider&&d.base_url===settingsSnapshot.base_url;$('keyState').textContent=t((d.api_key||(same&&state?.key_configured))?'keyPresent':'keyMissing');}
const baseProviderFields=updateProviderFields;
updateProviderFields=function(){baseProviderFields();syncConnectionHints();};
$('settings').elements.provider.onchange=updateProviderFields;
$('settings').elements.base_url.addEventListener('input',syncConnectionHints);
$('settings').elements.api_key.addEventListener('input',syncConnectionHints);
$('localPreset').onchange=()=>{if($('localPreset').value!=='custom')$('settings').elements.base_url.value=$('localPreset').value;else $('settings').elements.base_url.focus();markDirty();};
const baseLoadSettings=loadSettings;
loadSettings=async function(){await baseLoadSettings();await loadCheckCatalog();settingsSnapshot=await api('settings');dirty=false;$('draftState').textContent='';syncConnectionHints();try{$('sourceDocument').value=JSON.stringify(await api('data-sources'),null,2);sourcesDirty=false;}catch(e){$('sourceError').textContent=e.message;}};
function updateDirty(){const actual=collectSettings(),saved=settingsSnapshot;dirty=sourcesDirty||Object.entries(actual).some(([k,v])=>k==='api_key'||k==='imap_password'?Boolean(v):JSON.stringify(v)!==JSON.stringify(k==='check_modes'?Object.fromEntries(checkCatalog.map(row=>[row.name,saved?.check_modes?.[row.name]??row.mode])):saved?.[k]));$('draftState').textContent=dirty?t('unsaved'):'';}
async function saveData(data){const draftModes=collectSettings().check_modes;notice('');await api('settings',data);if(Object.hasOwn(data,'api_key'))$('settings').elements.api_key.value='';if(Object.hasOwn(data,'imap_password'))$('settings').elements.imap_password.value='';previewed=false;$('consent').checked=false;$('queueConsent').checked=false;$('entireFolder').checked=false;await refresh();if(selected&&!running){const m=state.messages.find(m=>m.id===selected);if(m)select(m);}settingsSnapshot=await api('settings');await loadCheckCatalog();if(!Object.hasOwn(data,'check_modes'))for(const [name,mode] of Object.entries(draftModes)){const field=$('settings').elements.namedItem('check_'+name);if(field)field.value=mode;}updateDirty();syncConnectionHints();}
async function connectionAction(verify){if(connectionBusy)return;connectionBusy=true;const buttons=[$('saveConnection'),$('saveOnly'),$('test'),$('loadModels')];buttons.forEach(b=>b.disabled=true);try{const data=connectionData();if(verify&&!data.model)throw Error(t('connectionNeedModel'));if(verify)await api('connection',data);await saveData({...data,privacy_mode:$('settings').elements.privacy_mode.value,language:$('settings').elements.language.value}); $('connectionResult').textContent=t(verify?'connectionVerifiedSaved':'connectionSaved');$('connectionState').textContent=t(state.connection_ok?'connectionVerified':'connectionUntested');}finally{connectionBusy=false;buttons.forEach(b=>b.disabled=false);}}
$('saveConnection').onclick=()=>safe(()=>connectionAction(true));$('saveOnly').onclick=()=>safe(()=>connectionAction(false));
$('test').onclick=()=>{showView('settings');safe(async()=>{const data=connectionData();if(!data.model)throw Error(t('connectionNeedModel'));$('test').disabled=true;try{await api('connection',data);$('connectionResult').textContent=t('draftVerified');}finally{$('test').disabled=false;}})};
$('loadModels').onclick=()=>safe(async()=>{$('loadModels').disabled=true;try{const r=await api('models',connectionData());$('modelOptions').replaceChildren(...r.models.map(id=>{const o=node('option');o.value=id;return o}));if(r.models.length===1)$('settings').elements.model.value=r.models[0];$('connectionResult').textContent=t('modelsLoaded');}finally{$('loadModels').disabled=false;}});
$('settings').onsubmit=e=>{e.preventDefault();safe(async()=>{const data=collectSettings();if(sourcesDirty)data.data_sources=JSON.parse($('sourceDocument').value);await saveData(data);if(sourcesDirty){$('settings').elements.data_sources_file.value=settingsSnapshot.data_sources_file;sourcesDirty=false;}dirty=false;$('draftState').textContent='';if(selected){const m=state.messages.find(m=>m.id===selected);if(m&&!running)select(m);}notice(t('saved'));});};
function profile(registry){for(const row of checkCatalog)$('settings').elements.namedItem('check_'+row.name).value=row.locked?'required':row.reference_keys.length?(registry?'conditional':'off'):row.mode;markDirty();notice(t('profileChanged'));}
$('basicProfile').onclick=()=>profile(false);$('registryProfile').onclick=()=>profile(true);
const baseSelect=select;
select=function(m){if(!m||running)return;baseSelect(m);$('removeMessage').hidden=m.source==='demo';$('welcome').hidden=true;$('messageBody').textContent='…';$('referenceNote').hidden=true;$('messageIdentity').textContent=t('messageRef')+': '+m.id.slice(0,12);$('scopeNote').textContent=t(state.privacy_mode==='evidence_only'?'scopeEvidence':'scopeText');safe(async()=>{let detail;try{detail=await api('messages/'+m.id);}catch(e){if(selected===m.id)$('messageBody').textContent=t('messageLoadFailed');throw e;}if(selected!==m.id)return;$('messageBody').textContent=detail.body||t('noBody');if(detail.body_truncated)$('messageBody').append(node('p',t('bodyTruncated')));if(detail.body_unavailable)$('messageBody').append(node('p',t('bodyUnavailable')));$('referenceNote').hidden=!(detail.reference_required&&!detail.reference_available);$('referenceNote').textContent=t('referenceMissing');if(detail.latest&&!running){renderJob(detail.latest);$('jobStatus').textContent=t('sameResult');}});};
function appendChecks(box,report){if(!report?.check_status)return;const section=node('section',undefined,'check-results');section.append(node('h3',t('doneChecks')));if(!report.checks_complete)section.append(node('p',t('checksIncomplete'),'notice'));for(const row of report.check_status)section.append(node('p',(checkCatalog.find(item=>item.name===row.tool)?.title?.[lang]||t(row.tool))+' · '+t(row.state)+' — '+t(row.reason)));box.append(section);}
function fillReport(box,result){box.replaceChildren();const report=result.report;if(!report){box.append(node('p',t(result.status)),node('p',t(result.events?.map(e=>e.error_code).find(c=>['context_limit','provider_unavailable','output_limit','tool_call_invalid','provider_error'].includes(c))||'failed')));return;}box.append(node('h3',t(report.verdict)),node('p',report.summary));box.append(node('p',t(report.analysis_scope?(report.analysis_scope==='redacted_text'?'scopeText':'scopeEvidence'):'scopeUnknown'),'muted'));appendChecks(box,report);for(const key of ['uncertainties','recommendations']){box.append(node('h3',t(key)));const ul=node('ul');for(const text of report[key]||[])ul.append(node('li',text));box.append(ul);}box.append(node('p',t('injectionScope'),'muted'));}
const baseRenderJob=renderJob;
renderJob=function(j){baseRenderJob(j);if(j.report){fillReport($('report'),j);$('report').classList.toggle('inconclusive',j.report.verdict==='INCONCLUSIVE');}if(j.status==='running')$('traceDetails').open=true;else if(j.report)$('traceDetails').open=false;};
$('cancelJob').onclick=()=>safe(async()=>{await api('cancel',{job_id:currentJob});notice(t('cancelPending'));});
function dataView(value){
 if(value===null||typeof value!=='object')return node('span',String(value??'—'));
 if(Array.isArray(value)){const list=node('ul');for(const item of value){const li=node('li');li.append(dataView(item));list.append(li);}return list;}
 const table=node('table',undefined,'data-table');for(const [key,item] of Object.entries(value)){const row=node('tr'),label=node('th',t(key).replaceAll('_',' ')),cell=node('td');label.scope='row';cell.append(dataView(item));row.append(label,cell);table.append(row);}return table;
}
$('preview').onclick=()=>safe(async()=>{const mid=selected,p=await api('preview',{message_id:mid});if(mid!==selected)return;$('payload').textContent=JSON.stringify(p,null,2);const box=$('previewSummary');box.replaceChildren(node('p',t('previewIntro')));for(const [name,value] of [[t('previewMode'),p.initial_message],...Object.entries(p.possible_tool_outputs||{}).map(([k,v])=>[checkCatalog.find(row=>row.name===k)?.title?.[lang]||t(k),v]),[t('onDemandTools'),p.on_demand_tools||[]]]){const d=node('details');d.append(node('summary',name),dataView(value));box.append(d);}$('outgoing').hidden=false;$('outgoing').open=true;previewed=true;});
$('removeMessage').onclick=()=>safe(async()=>{await api('remove-message',{message_id:selected});selected=null;lastJob=null;$('detail').hidden=true;$('empty').hidden=false;await refresh();});
let restoring=false;
const baseRefresh=refresh;
refresh=async function(){await baseRefresh();$('connectAI').hidden=state.configured;$('connectionState').textContent=t(state.connection_ok?'connectionVerified':'connectionUntested');if(!state.configured&&currentView==='settings')$('setup').open=true;syncConnectionHints();if(state.active_job&&!running&&!restoring){restoring=true;try{const m=state.messages.find(m=>m.id===state.active_job.message_id);if(m){$('sourceFilter').value=m.source==='demo'?'demo':'own';showView('review');select(m);}currentJob=state.active_job.job_id;running=true;$('analyze').disabled=true;$('file').disabled=true;$('imap').disabled=true;poll();}finally{restoring=false;}}};
async function showReport(id){showView('history',false);const box=$('history');const result=await api('reports/'+id);box.replaceChildren();const detail=node('section',undefined,'report-card');detail.append(node('h2',t('reportResult')));const body=node('div');fillReport(body,result);detail.append(body);box.append(detail);}
async function queueLoad(){const q=await api('queue?page='+queuePage);$('queueState').textContent=q.error?t('queueFault'):t(q.discovering&&!q.paused?'discovering':q.state);$('queueScope').textContent=t('scope')+': '+(q.host||'—')+' / '+q.folder+' · '+(q.since?t('since')+' '+q.since:t('allMail'))+' · '+t('hourly')+': '+q.per_hour+' · '+t('callLimit')+': '+q.call_limit;$('entireFolderWrap').hidden=Boolean(q.since);$('queueCounts').textContent=Object.entries(q.counts).map(([k,v])=>t(k)+': '+v).join(' · ')+' · '+t('dailyCalls')+': '+q.daily_calls+(q.resume_at?' · '+t('resumeAt')+': '+new Date(q.resume_at*1000).toLocaleString(lang==='cs'?'cs-CZ':'en-GB'):'');$('queueError').textContent=q.error?t('queueFault'):'';$('queueConsentWrap').hidden=!state?.external;$('queueResume').disabled=!q.paused;$('queuePause').disabled=q.paused;$('queuePage').textContent=String(queuePage+1);$('queuePrev').disabled=queuePage===0;$('queueNext').disabled=q.items.length<50;const signature=JSON.stringify([q.items,lang,queuePage]);if(signature===lastQueueSignature)return;lastQueueSignature=signature;const box=$('queueItems');box.replaceChildren();if(!q.items.length)box.append(node('p',t('noQueue'),'muted'));for(const row of q.items){const el=node('div',undefined,'history-row');el.append(node('span',row.folder+' · UID '+row.uid+' · '+row.id.slice(0,12)+' · '+t(row.status)+' · '+t('attemptLabel')+': '+row.attempts));const actions=node('div',undefined,'row-actions');if(row.report_id){const b=node('button',t('openReport'),'secondary');b.onclick=()=>safe(()=>showReport(row.report_id));actions.append(b);}if(['pending','running','failed','cancelled'].includes(row.status)){const action=['failed','cancelled'].includes(row.status)?'retry':'cancel';const b=node('button',t(action),'secondary');b.onclick=()=>safe(async()=>{await api('queue/'+action,{id:row.id});await queueLoad()});actions.append(b);}el.append(actions);box.append(el);}};
$('queueResume').onclick=()=>safe(async()=>{if(dirty)throw Error(t('saveFirst'));$('queueResume').disabled=true;try{await api('queue/resume',{consent:$('queueConsent').checked,entire_folder:$('entireFolder').checked});await queueLoad();}finally{await queueLoad().catch(()=>{});}});
$('queuePause').onclick=()=>safe(async()=>{await api('queue/pause',{});$('queueConsent').checked=false;await queueLoad();});
$('queuePrev').onclick=()=>safe(async()=>{queuePage=Math.max(0,queuePage-1);await queueLoad()});$('queueNext').onclick=()=>safe(async()=>{queuePage++;await queueLoad()});
historyLoad=async function(){const list=await api('reports?page='+reportsPage);$('reportsPrev').disabled=reportsPage===0;$('reportsNext').disabled=list.length<100;$('reportsPage').textContent=String(reportsPage+1);$('history').replaceChildren();if(!list.length)$('history').append(node('p',t('noHistory'),'muted'));for(const r of list){const d=node('details');const m=state?.messages.find(m=>m.id===r.message_id);d.append(node('summary',(m?.subject||t('messageRef')+' '+r.message_id.slice(0,12))+' · '+new Date(r.created*1000).toLocaleString(lang==='cs'?'cs-CZ':'en-GB')+' · '+t(r.result.report?.verdict||r.result.status)));let loaded=false;d.ontoggle=()=>{if(!d.open||loaded)return;loaded=true;safe(async()=>{try{const result=await api('reports/'+r.id);const content=node('div');fillReport(content,result);d.append(content);const raw=node('details');raw.append(node('summary',t('rawDetails')),node('pre',JSON.stringify(result,null,2)));d.append(raw);}catch(e){loaded=false;throw e;}});};$('history').append(d);}};
$('reportsPrev').onclick=()=>safe(async()=>{reportsPage=Math.max(0,reportsPage-1);await historyLoad()});$('reportsNext').onclick=()=>safe(async()=>{reportsPage++;await historyLoad()});
const baseTranslate=translate;
translate=function(){baseTranslate();for(const row of checkCatalog){const label=document.querySelector('[data-check-label="'+row.name+'"]');if(label)label.textContent=row.title[lang]||row.title.en||row.name;}if(state){$('connectionState').textContent=t(state.connection_ok?'connectionVerified':'connectionUntested');$('scopeNote').textContent=t(state.privacy_mode==='evidence_only'?'scopeEvidence':'scopeText');}syncConnectionHints();};
showView('review');translate();
safe(async()=>{await loadSettings();await refresh();await queueLoad();});
